fn invert_array(a: &mut Vec<i32>) {
    let n = a.len();
    if n <= 1 {
        return;
    }

    let mut i = 0;
    let mut j = n - 1;
    while i < j {
        a.swap(i, j);
        i += 1;
        j -= 1;
    }
}

